#include <gtest/gtest.h>
#include <datamunge/algorithms/dixon.hpp>
#include <algorithm>
#include <cmath>
#include <limits>
#include <numeric>
#include <vector>
using namespace datamunge::algorithms;
namespace {
std::uint64_t addmod(std::uint64_t a,std::uint64_t b,std::uint64_t n){return a>=n-b?a-(n-b):a+b;}
std::uint64_t product(std::uint64_t a,std::uint64_t b,std::uint64_t n){a%=n;b%=n;std::uint64_t r=0;while(b){if(b&1)r=addmod(r,a,n);a=addmod(a,a,n);b>>=1;}return r;}
std::vector<std::uint64_t> small_primes(int count){std::vector<std::uint64_t> p;for(std::uint64_t x=2;p.size()<static_cast<std::size_t>(count);++x){bool yes=true;for(std::uint64_t d=2;d<=x/d;++d)if(x%d==0){yes=false;break;}if(yes)p.push_back(x);}return p;}
DixonCollection oracle_collection(std::uint64_t n,int k,std::size_t budget,bool stop){DixonCollection c;c.n=n;c.base=small_primes(k);auto r=static_cast<std::uint64_t>(std::sqrt(static_cast<long double>(n)));while(r>n/r)--r;while(r+1<=n/(r+1))++r;c.start=r+1;
for(std::size_t offset=0;offset<budget && (!stop||c.relations.size()<static_cast<std::size_t>(k+1));++offset){++c.scanned;auto x=c.start+offset,q=product(x,x,n),left=q;if(!q){++c.zero_residues;continue;}std::vector<unsigned> e(k);for(int p=0;p<k;++p)while(left%c.base[p]==0){left/=c.base[p];++e[p];}if(left==1)c.relations.push_back({x,q,offset,e});}return c;}
void equal_collections(const DixonCollection&a,const DixonCollection&b){ASSERT_EQ(a.n,b.n);ASSERT_EQ(a.start,b.start);ASSERT_EQ(a.base,b.base);ASSERT_EQ(a.scanned,b.scanned);ASSERT_EQ(a.zero_residues,b.zero_residues);ASSERT_EQ(a.relations.size(),b.relations.size());for(std::size_t r=0;r<a.relations.size();++r){EXPECT_EQ(a.relations[r].x,b.relations[r].x);EXPECT_EQ(a.relations[r].residue,b.relations[r].residue);EXPECT_EQ(a.relations[r].offset,b.relations[r].offset);EXPECT_EQ(a.relations[r].exponents,b.relations[r].exponents);}}
void verify(const DixonTrace&t){const auto&c=t.collection;const auto R=c.relations.size(),K=c.base.size();std::vector<std::vector<bool>> m(R,std::vector<bool>(K)),sel(R,std::vector<bool>(R));for(std::size_t r=0;r<R;++r){sel[r][r]=true;for(std::size_t p=0;p<K;++p)m[r][p]=c.relations[r].exponents[p]%2;}
std::size_t rank=0,xors=0;for(std::size_t p=0;p<K&&rank<R;++p){std::size_t pivot=rank;while(pivot<R&&!m[pivot][p])++pivot;if(pivot==R)continue;std::swap(m[pivot],m[rank]);std::swap(sel[pivot],sel[rank]);for(std::size_t r=0;r<R;++r)if(r!=rank&&m[r][p]){for(std::size_t j=0;j<K;++j)m[r][j]=m[r][j]!=m[rank][j];for(std::size_t j=0;j<R;++j)sel[r][j]=sel[r][j]!=sel[rank][j];++xors;}++rank;}
std::size_t divisions=0;for(std::size_t i=0;i<c.scanned;++i){auto q=product(c.start+i,c.start+i,c.n);if(!q)continue;for(auto p:c.base)while(q%p==0){q/=p;++divisions;}}EXPECT_EQ(divisions,t.successful_divisions);EXPECT_EQ(rank,t.rank);EXPECT_EQ(xors,t.row_xors);std::size_t deps=0,cells=K;for(auto&r:c.relations)cells+=K+3;
std::uint64_t result=0;for(std::size_t r=rank;r<R;++r){ASSERT_LT(deps,t.dependencies.size());const auto&d=t.dependencies[deps++];std::vector<std::size_t> ids;std::vector<std::uint64_t>sums(K);std::uint64_t X=1,Y=1;for(std::size_t j=0;j<R;++j)if(sel[r][j]){ids.push_back(j);X=product(X,c.relations[j].x,c.n);for(std::size_t p=0;p<K;++p)sums[p]+=c.relations[j].exponents[p];}ASSERT_FALSE(ids.empty());EXPECT_EQ(ids,d.relation_indices);EXPECT_EQ(sums,d.exponent_sums);for(std::size_t p=0;p<K;++p){EXPECT_EQ(sums[p]%2,0);for(std::uint64_t e=0;e<sums[p]/2;++e)Y=product(Y,c.base[p],c.n);}EXPECT_EQ(X,d.X);EXPECT_EQ(Y,d.Y);EXPECT_EQ(product(X,X,c.n),product(Y,Y,c.n));auto minus=std::gcd(X>Y?X-Y:Y-X,c.n),plus=std::gcd(addmod(X,Y,c.n),c.n);EXPECT_EQ(minus,d.gcd_minus);EXPECT_EQ(plus,d.gcd_plus);cells+=ids.size()+K+4;if(minus>1&&minus<c.n)result=minus;else if(plus>1&&plus<c.n)result=plus;if(result)break;}
EXPECT_EQ(deps,t.dependencies.size());EXPECT_EQ(result,t.factor);EXPECT_EQ(cells,t.captured_cells);if(R>K)EXPECT_LT(rank,R);if(t.factor){EXPECT_GT(t.factor,1);EXPECT_LT(t.factor,c.n);EXPECT_EQ(c.n%t.factor,0);}
}
}
TEST(DixonTrace, HandCongruenceAndOriginalFourInputs){const auto t=dixon_factor_trace(77,3,10);equal_collections(t.collection,oracle_collection(77,3,10,true));verify(t);ASSERT_EQ(t.dependencies.size(),1);EXPECT_EQ(t.dependencies[0].relation_indices,(std::vector<std::size_t>{0}));EXPECT_EQ(t.factor,7);EXPECT_EQ(t.dependencies[0].gcd_plus,11);EXPECT_EQ(t.rank,1);for(auto n:{8051ULL,15347ULL,92434447ULL,16843009ULL}){const auto a=dixon_factor_trace(n,30);verify(a);EXPECT_NE(a.factor,0);EXPECT_EQ(a.factor,dixon_factor(n,30));}}
TEST(DixonTrace, ExhaustiveSmallModuliBasesAndBudgetsMatchIndependentScanAndBooleanElimination){for(std::uint64_t n=2;n<=300;++n)for(int k=1;k<=8;++k)for(auto budget:{0u,1u,7u,60u}){auto t=dixon_factor_trace(n,k,budget);equal_collections(t.collection,oracle_collection(n,k,budget,true));verify(t);} }
TEST(DixonCollection, FullWindowMatchesIndependentScanAndOriginalDensity){for(std::uint64_t n=2;n<=120;++n)for(int k=1;k<=6;++k)equal_collections(dixon_collect(n,k,90),oracle_collection(n,k,90,false));auto c=dixon_collect(92434447,30,4000);EXPECT_EQ(c.scanned,4000);EXPECT_EQ(c.relations.size(),25);auto z=dixon_collect(4,3,20);EXPECT_GT(z.zero_residues,0);equal_collections(z,oracle_collection(4,3,20,false));}
TEST(DixonTrace, DynamicPrimeAndRelationVectorsCrossAllMachineWordBoundaries){for(int k:{63,64,65,127,128,129}){auto t=dixon_factor_trace(77,k,400);ASSERT_EQ(t.collection.relations.size(),k+1);equal_collections(t.collection,oracle_collection(77,k,400,true));verify(t);EXPECT_EQ(t.factor,dixon_factor(77,k));}for(int k:{63,64,65,127,128,129}){const auto p=small_primes(k).back();const std::uint64_t n=1000000-p;auto high=dixon_factor_trace(n,k,4000);ASSERT_FALSE(high.collection.relations.empty());EXPECT_EQ(high.collection.relations[0].residue,p);EXPECT_EQ(high.collection.relations[0].exponents.back(),1);equal_collections(high.collection,oracle_collection(n,k,4000,true));verify(high);}auto prime=dixon_factor_trace(13,129,400);verify(prime);ASSERT_EQ(prime.collection.relations.size(),130);EXPECT_EQ(prime.factor,0);bool high_selection=false;for(auto&d:prime.dependencies)for(auto id:d.relation_indices)high_selection|=id>=128;EXPECT_TRUE(high_selection);auto t=dixon_factor_trace(77,4096,0,4096);EXPECT_EQ(t.collection.base.size(),4096);EXPECT_EQ(t.captured_cells,4096);}
TEST(DixonTrace, FullWidthModularProductsAndSquareRootBoundary){for(auto n:std::vector<std::uint64_t>{std::numeric_limits<std::uint64_t>::max(),std::numeric_limits<std::uint64_t>::max()-58,18446744065119617025ULL,4294967297ULL}){auto c=dixon_collect(n,12,80);equal_collections(c,oracle_collection(n,12,80,false));auto t=dixon_factor_trace(n,12,80);verify(t);}EXPECT_EQ(dixon_collect(std::numeric_limits<std::uint64_t>::max(),1,0).start,4294967296ULL);EXPECT_EQ(dixon_collect(81,1,0).start,10);}
TEST(DixonTrace, CaptureLimitsValidationAndOwnedStorage){auto t=dixon_factor_trace(77,3,10);EXPECT_NO_THROW(dixon_factor_trace(77,3,10,t.captured_cells));
EXPECT_THROW(dixon_factor_trace(77,3,10,t.captured_cells-1),std::length_error);
EXPECT_NO_THROW(dixon_factor_trace(77,3,10,0));
EXPECT_THROW(dixon_collect(77,3,0,2),std::length_error);
EXPECT_NO_THROW(dixon_collect(77,3,0,3));
EXPECT_THROW(dixon_collect(77,3,1,8),std::length_error);
EXPECT_NO_THROW(dixon_collect(77,3,1,9));
for(int k:{-1,0,4097,std::numeric_limits<int>::max()}){EXPECT_THROW(dixon_factor(77,k),std::invalid_argument);
EXPECT_THROW(dixon_collect(77,k,0,1),std::invalid_argument);}
EXPECT_THROW(dixon_factor(0,3),std::invalid_argument);
EXPECT_THROW(dixon_factor_trace(1,3),std::invalid_argument);
EXPECT_THROW(dixon_collect(77,3,std::numeric_limits<std::size_t>::max()),std::overflow_error);
auto copy=t;t.collection.relations[0].exponents[0]=100;t.dependencies[0].X=999;EXPECT_EQ(copy.collection.relations[0].exponents[0],2);EXPECT_EQ(copy.dependencies[0].X,9);}
TEST(DixonTrace, ADependencyCanBeTrivialAndFailureIsNotAPrimalityCertificate){auto t=dixon_factor_trace(13,3,20);verify(t);EXPECT_EQ(t.factor,0);ASSERT_FALSE(t.dependencies.empty());for(auto&d:t.dependencies){EXPECT_TRUE(d.gcd_minus==1||d.gcd_minus==13);EXPECT_TRUE(d.gcd_plus==1||d.gcd_plus==13);}auto empty=dixon_factor_trace(77,3,0);EXPECT_EQ(empty.factor,0);EXPECT_EQ(empty.collection.scanned,0);auto single=dixon_factor_trace(77,3,1);EXPECT_EQ(single.factor,7);verify(single);}
